	In this paper, we consider the linearly constrained convex optimization model,


\begin{equation*}
		\mbox{(P)} \quad\quad \min  \left\{ \Psi\left(x\right) \, : \, \AAA x = b, \; x \in \real^n\right\},
	\end{equation*}

	where $\Psi:\real^{n} \rightarrow \erl$ is a proper, lower semi-continuous and convex function, $\AAA: \real^n\to \real^m$ is a linear mapping, and $b \in \real^{m}$. Throughout this work, the feasible set of problem (P) is denoted by  $\FFF = \left\{ x \in \rr^{n} : \, \AAA x = b \right\}$.
\medskip

	 Despite its apparent simplicity, with an additional structural/data information on the objective function or/and on the linear mapping (see examples below), the optimization model (P) essentially captures a very wide range of convex optimization problems arising in many modern applications. Since we are interested in analyzing this model also in the strongly convex case, we instead assume that $\Psi\left(\cdot\right)$ is $\sigma$-strongly convex with $\sigma \geq 0$ (\ie when $\sigma = 0$ we recover the convex setting). At this juncture, it is important to mention that in many applied problems the function $\Psi$ is defined by the sum of two or more functions, see \eg \cite{CP2016-B}. In such cases,  it is enough to assume that {\em one} of the functions is $\sigma$-strongly convex, see Section \ref{SSec:Block} for more details.


	We conclude this section with some basic properties of Lagrangians in convex optimization. For the equality constrained problem given in model (P), the {\em Lagrangian} $\Lag: \rr^{n} \times \rr^{m} \to \erl$ is defined by


\begin{equation} \label{D:Lag}
		\Lag\left(x , y\right) \equiv \Psi\left(x\right) + \act{y , \AAA x - b},
	\end{equation}

	where $y \in \real^{m}$ is the {\em Lagrange multiplier} associated with the linear constraint $\AAA x = b$. In this study, we will also use the \textit{augmented Lagrangian} associated to problem (P), which is defined by 	


\begin{equation} \label{D:AugLA}
		\Lag_{\rho}\left(x ,  y\right) := \Lag\left(x , y\right) + \frac{\rho}{2}\norm{\AAA x - b}^{2} = \Psi\left(x\right) + \act{y , \AAA x - b} + \frac{\rho}{2}\norm{\AAA x - b}^{2},
	\end{equation}

	where $\rho > 0$ is a {\em penalty parameter}. Clearly, when $\rho = 0$ we recover the Lagrangian itself, \ie $\Lag \equiv \Lag_{0}$.


\begin{assumption} \label{A:ConvLag}
		The Lagrangian $\Lag$ has a saddle point, that is, there exists a pair $\left(x^{\ast} , y^{\ast}\right)$ such that
		\begin{equation} \label{A:ConvLag:1}
			\Lag\left(x^{\ast} , y\right) \leq \Lag\left(x^{\ast} , y^{\ast}\right) \leq \Lag\left(x , y^{\ast}\right), \quad \forall \,\, x \in \real^{n}, \quad \forall \,\, y\in \real^{m}.
		\end{equation}
	\end{assumption}

	We end this section with some notations that will be used throughout the paper. We denote by $\bbS_{+}^{n}$ and $\bbS_{++}^{n}$ the sets of all $n \times n$ {\em positive semi-definite matrices} and {\em positive definite matrices}, respectively. Given $P \in \bbS_{+}^{n}$, $\norm{u}_{P} := \sqrt{\act{u , Pu}}$ stands for the semi-norm of $u \in \real^{n}$. For any $u , v , w \in \real^{n}$, we define the following quantity 		


\begin{equation} \label{D:Delta}
		\Delta_{P}\left(u , v , w\right) := \frac{1}{2}\left(\norm{u - v}_{P}^{2} - \norm{u - w}_{P}^{2}\right).
	\end{equation}

	In the case that $P = I$, where $I_{n}$ denotes the $n \times n$ {\em identity matrix}, we simply denote $\Delta := \Delta_{P}$.


\begin{definition}[Nice primal algorithmic map] \label{D:AlgoMapNice}
		Given the parameters $\rho , t > 0$, we let $\rho_{t} = \rho$ and $\tau_{t} = 1$ (when $\sigma = 0$) or $\rho_{t} = \rho t$ and $\tau_{t} = t$ (when $\sigma > 0$). A primal algorithmic map $\SSS_{t} : \real^{n} \times \real^{m} \rightarrow \real^{n}$, which is applied on the augmented Lagrangian $\Lag_{\rho_{t}}\left(z , \lambda\right)$, that generates $z^{+}$ via $z^{+} \in \SSS_{t}\left(z , \lambda\right)$, is called {\em \nice}\hspace{-0.05in} if there exist a parameter $\delta \in \left(0 , 1\right]$ and matrices $P , Q \in \bbS_{+}^{n}$, such that for any $\xi \in \FFF$ we have
		\begin{equation} \label{D:AlgoMapNice:1}
			\Lag_{\rho_{t}}\left(z^{+} , \lambda\right) - \Lag_{\rho_{t}}\left(\xi , \lambda\right) \leq \tau_{t}\Delta_{P}\left(\xi , z , z^{+}\right) - \frac{\tau_{t}}{2}\norm{z^{+} - z}_{Q}^{2} - \frac{\sigma}{2}\norm{\xi - z^{+}}^{2} - \frac{\delta\rho_{t}}{2}\norm{\AAA z^{+} - b}^{2}.
		\end{equation}				
	\end{definition}

    \begin{center}
    		\fbox{\parbox{16.5cm}{{\bf FLAG -- Faster LAGrangian based method}
			\begin{enumerate}
				\item[1.] {\bf Input:} The problem data $[\Psi, \AAA, b, \sigma]$, and a \nice primal algorithmic map $\SSS_{t}\left(\cdot\right)$.
				\item[2.] {\bf Initialization:} Set $\mu \in \left(0 , \delta\right]$ and $\rho > 0$. Start with any $\left(x^{0} , z^{0} , y^{0}\right) \in \rr^{n} \times \rr^{n} \times \rr^{m}$, $t_{0} = 1$.
            		\item[3.] {\bf Iterations:} Sequences $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ and $\seq{t}{k}$ are generated as follows: for each $k \geq 0$
                		\begin{enumerate}
                    		\item[3.1.] If $\sigma = 0$, let $\rho_{k} = \rho$, or, if $\sigma > 0$, let $\rho_{k} = \rho t_{k}$. Compute
                    			\begin{equation} \label{GL:Lambda}
                    				\lambda^{k} = y^{k} + \rho_{k}\left(t_{k} - 1\right)\left(\AAA x^{k} -b\right).
                    			\end{equation}    		
                    		\item[3.2.] Update the sequence $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ by
                       		\begin{align}
                           		z^{k + 1} & \in \SSS_{t_{k}}\left(z^{k} , \lambda^{k}\right), \label{FGL:PriStep} \\
                           		y^{k + 1} & = y^{k} + \mu\rho_{k}\left(\AAA z^{k + 1} - b\right), \label{FGL:MultiStep} \\
                           		x^{k + 1} & = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}. \label{FGL:AccStep}
                       		\end{align}
 						\item[3.3.] Update the sequence $\seq{t}{k}$ by solving the equation $t_{k + 1}^{p} - t_{k}^{p} = t_{k + 1}^{p - 1}$, \ie
                       		\begin{equation} \label{FGL:Tk}
                        			t_{k + 1} = \left\{\begin{matrix}
                        			t_{k}  + 1, & \hspace{-0.6in} p = 1 \,\, \text{(convex case)}, \vspace{0.1in} \\
                        			(1 + \sqrt{1 + 4t_{k}^{2}})/2, & p =2 \,\, \text{(strongly convex case)}.
                        			\end{matrix} \right.
							\end{equation}
                    		\end{enumerate}
			\end{enumerate}\vspace{-0.2in}}}
	\end{center}


	In FLAG, once the \nice algorithmic map $\SSS_{t}\left(\cdot\right)$ has been chosen, \ie a parameter $\delta \in \left(0 , 1\right]$ and matrices $P , Q \in \bbS_{+}^{n}$, have been determined, Definition \ref{D:AlgoMapNice} translates in terms of the iterative sequence $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ produced by FLAG as follows: for each $k \geq 0$ and $\xi \in \FFF$,


\begin{align}
		\Lag_{\rho_{k}}\left(z^{k + 1} , \lambda^{k}\right) - \Lag_{\rho_{k}}\left(\xi , \lambda^{k}\right) & \leq \tau_{k}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\tau_{k}}{2}\norm{z^{k + 1} - z^{k}}_{Q}^{2}  - \frac{\sigma}{2}\norm{\xi- z^{k + 1}}^{2} \nonumber \\
		& - \frac{\delta\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2}, \label{AlgoMapNiceProperty}
	\end{align}

	where $\tau_{k} = 1$ and $\rho_{k} = \rho$ (when $\sigma = 0$) or $\tau_{k} = t_{k}$ and $\rho_{k} = \rho t_{k}$ (when $\sigma > 0$).


	Before proceeding, we recall the following fundamental {\em Pythagoras three-points identity} that is frequently used below. Given any matrix $P \in \bbS_{+}^{n}$, we have


\begin{equation} \label{Pyth}
		2\act{u - w , P\left(w - v\right)} =  \norm{u - v}_{P}^{2}- \norm{u - w}_{P}^{2} - \norm{v - w}_{P}^{2}, \quad \forall \,\, u , v , w \in \real^{n}.
	\end{equation}

	We also recall the main parameter sequences introduced in FLAG and which, for convenience, will be used often and systematically as follows:
   \begin{equation*}
    		\rho_{k} = \rho t_{k}^{p - 1} ,\; (\rho>0)\; \quad \text{and} \quad t_{k}^{p} - t_{k - 1}^{p} = t_{k}^{p - 1},\; (t_{-1} \equiv 0 \;\text{and}\; t_0 = 1),
	\end{equation*}	
	where $p = 1$ (if $\sigma = 0$) or $p = 2$ (if $\sigma > 0$), and $\tau_{k} = 1$ if $\sigma = 0$, or $\tau_{k} = t_{k}$ if $\sigma > 0$. We will also often use the following expression. For any $k\geq 0$ and any $\xi \in {\cal F}$ we define,


\begin{equation}\label{laggap}
		s_{k} := \Lag_{\rho t_{k - 1}^{p}}\left(x^{k} , \eta\right) - \Lag_{\rho t_{k - 1}^{p}}\left(\xi , \eta\right) \equiv \Lag_{\rho t_{k - 1}^{p}}\left(x^{k} , \eta\right) - \Psi(\xi).
	 \end{equation}

	Throughout the rest of this section, recalling the fact that the set of optimal dual solutions is compact (see Section \ref{Sec:Form}), we take $c > 0$ to be a constant for which $c \geq 2\norm{y^{\ast}}$, where $y^{\ast}$ is an optimal solution of the dual problem.

