	\end{assumption}

\begin{equation} \label{D:Delta}
		\Delta_{P}\left(u , v , w\right) := \frac{1}{2}\left(\norm{u - v}_{P}^{2} - \norm{u - w}_{P}^{2}\right).
	\end{equation}

\begin{definition}[Nice primal algorithmic map] \label{D:AlgoMapNice}
		Given the parameters $\rho , t > 0$, we let $\rho_{t} = \rho$ and $\tau_{t} = 1$ (when $\sigma = 0$) or $\rho_{t} = \rho t$ and $\tau_{t} = t$ (when $\sigma > 0$). A primal algorithmic map $\SSS_{t} : \real^{n} \times \real^{m} \rightarrow \real^{n}$, which is applied on the augmented Lagrangian $\Lag_{\rho_{t}}\left(z , \lambda\right)$, that generates $z^{+}$ via $z^{+} \in \SSS_{t}\left(z , \lambda\right)$, is called {\em \nice}\hspace{-0.05in} if there exist a parameter $\delta \in \left(0 , 1\right]$ and matrices $P , Q \in \bbS_{+}^{n}$, such that for any $\xi \in \FFF$ we have
		\begin{equation} \label{D:AlgoMapNice:1}
			\Lag_{\rho_{t}}\left(z^{+} , \lambda\right) - \Lag_{\rho_{t}}\left(\xi , \lambda\right) \leq \tau_{t}\Delta_{P}\left(\xi , z , z^{+}\right) - \frac{\tau_{t}}{2}\norm{z^{+} - z}_{Q}^{2} - \frac{\sigma}{2}\norm{\xi - z^{+}}^{2} - \frac{\delta\rho_{t}}{2}\norm{\AAA z^{+} - b}^{2}.
		\end{equation}				
	\end{definition}

    \begin{center}
    		\fbox{\parbox{16.5cm}{{\bf FLAG -- Faster LAGrangian based method}
			\begin{enumerate}
				\item[1.] {\bf Input:} The problem data $[\Psi, \AAA, b, \sigma]$, and a \nice primal algorithmic map $\SSS_{t}\left(\cdot\right)$.
				\item[2.] {\bf Initialization:} Set $\mu \in \left(0 , \delta\right]$ and $\rho > 0$. Start with any $\left(x^{0} , z^{0} , y^{0}\right) \in \rr^{n} \times \rr^{n} \times \rr^{m}$, $t_{0} = 1$.
            		\item[3.] {\bf Iterations:} Sequences $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ and $\seq{t}{k}$ are generated as follows: for each $k \geq 0$
                		\begin{enumerate}
                    		\item[3.1.] If $\sigma = 0$, let $\rho_{k} = \rho$, or, if $\sigma > 0$, let $\rho_{k} = \rho t_{k}$. Compute
                    			\begin{equation} \label{GL:Lambda}
                    				\lambda^{k} = y^{k} + \rho_{k}\left(t_{k} - 1\right)\left(\AAA x^{k} -b\right).
                    			\end{equation}    		
                    		\item[3.2.] Update the sequence $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ by
                       		\begin{align}
                           		z^{k + 1} & \in \SSS_{t_{k}}\left(z^{k} , \lambda^{k}\right), \label{FGL:PriStep} \\
                           		y^{k + 1} & = y^{k} + \mu\rho_{k}\left(\AAA z^{k + 1} - b\right), \label{FGL:MultiStep} \\
                           		x^{k + 1} & = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}. \label{FGL:AccStep}
                       		\end{align}
 						\item[3.3.] Update the sequence $\seq{t}{k}$ by solving the equation $t_{k + 1}^{p} - t_{k}^{p} = t_{k + 1}^{p - 1}$, \ie
                       		\begin{equation} \label{FGL:Tk}
                        			t_{k + 1} = \left\{\begin{matrix}
                        			t_{k}  + 1, & \hspace{-0.6in} p = 1 \,\, \text{(convex case)}, \vspace{0.1in} \\
                        			(1 + \sqrt{1 + 4t_{k}^{2}})/2, & p =2 \,\, \text{(strongly convex case)}.
                        			\end{matrix} \right.
							\end{equation}
                    		\end{enumerate}
			\end{enumerate}\vspace{-0.2in}}}
	\end{center}

