\begin{theorem}[A fast non-ergodic function values and feasibility violation rates] \label{T:FGLrate}
		Let $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ be a sequence generated by FLAG. Suppose that $\sigma > 0$ and $0 \preceq P \preceq \left(\sigma/2\right)I_{n}$. Then, for any optimal solution $x^{\ast}$ of problem (P), we have
   		\begin{align}
			\Psi\left(x^{N}\right) - \Psi\left(x^{\ast}\right) & \leq \frac{B_{\rho , c}\left(x^{\ast}\right)}{2N^{2}}, \label{T:FGLrate:1} \\
       		\norm{\AAA x^{N} - b} & \leq \frac{B_{\rho , c}\left(x^{\ast}\right)}{cN^{2}}, \label{T:FGLrate:2}
		\end{align}
		where $B_{\rho , c}\left(x^{\ast}\right) := 4\left(\norm{x^{\ast} - z^{0}}_{P}^{2} + \frac{1}{\mu\rho}\left(\norm{y^{0}} + c\right)^{2}\right)$.
	\end{theorem}

\begin{proof}
		From Lemma \ref{L:FGLMain}, after we substitute $\xi = x^{\ast}$ and $p = 2$ (recall that $\rho_{k} = \rho t_{k}$ and $\tau_{k} = t_{k}$), we obtain
		\begin{equation*}
			t_{k}^{2}s_{k + 1} - t_{k - 1}^{2}s_{k} \leq t_{k}^{2}\Delta_{P}\left(x^{\ast} , z^{k} , z^{k + 1}\right) - \frac{t_{k}\sigma}{2}\norm{x^{\ast} - z^{k + 1}}^{2} + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right).
		\end{equation*}
		Using the definition of $\Delta_{P}$ and $\Delta$ (see \eqref{D:Delta}) and the fact that $P \preceq \left(\sigma/2\right)I_{n}$ we have that
		\begin{align*}
			t_{k}^{2}s_{k + 1} - t_{k - 1}^{2}s_{k} & \leq \frac{t_{k}^{2}}{2}\left(\norm{x^{\ast} - z^{k}}_{P}^{2} - \norm{x^{\ast} - z^{k + 1}}_{P}^{2}\right) - t_{k}\norm{x^{\ast} - z^{k + 1}}_{P}^{2} + \frac{1}{2\mu\rho}\left(\norm{\eta - y^{k}}^{2} -  \norm{\eta - y^{k + 1}}^{2}\right) \nonumber \\
			& \leq \frac{1}{2}\left(t_{k}^{2}\norm{x^{\ast} - z^{k}}_{P}^{2} - t_{k + 1}^{2}\norm{x^{\ast} - z^{k + 1}}_{P}^{2}\right) + \frac{1}{2\mu\rho}\left(\norm{\eta - y^{k}}^{2} - \norm{\eta - y^{k + 1}}^{2}\right),
		\end{align*}
		where the last inequality follows from Lemma \ref{L:Tk}(ii). Summing this inequality for all $k = 0 , 1 , \ldots , N - 1$ (recall that $t_{-1} = 0$ and $t_{0} = 1$), it follows (where we use  the definition of $s_{N}$, see \eqref{laggap}, for the first inequality below)
		\begin{equation*}
	t_{N - 1}^{2}\left(\Psi\left(x^{N}\right) - \Psi\left(x^{\ast}\right) + \act{\eta , \AAA x^{N} - b}\right) \leq	t_{N - 1}^{2}s_{N} - t_{-1}^{2}s_{0} \leq \frac{1}{2}\norm{x^{\ast} - z^{0}}_{P}^{2} + \frac{1}{2\mu\rho}\norm{\eta - y^{0}}^{2}.
		\end{equation*}
		Therefore, by taking the maximum of both sides over $\norm{\eta} \leq c$, proves that (recall that $t_{N - 1}^{2} \geq N^{2}/4$ using Lemma \ref{L:Tk}(ii))
		\begin{equation*}
			\Psi\left(x^{N}\right) - \Psi\left(x^{\ast}\right) + c\norm{\AAA x^{N} - b} \leq \frac{B_{\rho , c}\left(x^{\ast}\right)}{2N^{2}} := \beta,
		\end{equation*}
		from which the estimate \eqref{T:FGLrate:1} immediately follows. Moreover, since $\left(x^{\ast} , y^{\ast}\right)$ is a saddle point of problem (P), with $c \geq 2\norm{y^{\ast}}$, using the above inequality it follows that
		\begin{equation*}
			c\norm{\AAA x^{N} - b} \leq \Psi\left(x^{\ast}\right) - \Psi\left(x^{N}\right) + \beta \leq \act{y^{\ast} , \AAA x^{N} - b} + \beta \leq \frac{c}{2}\norm{\AAA x^{N} - b} + \beta,
		\end{equation*}
		and the desired estimate \eqref{T:FGLrate:2} is proved.
	\end{proof}

\begin{lemma} \label{L:FGLIter}
		Let $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ be a sequence generated by FLAG. Then, for any $\xi \in \FFF$, $\eta \in \real^{m}$ and $k \geq 0$, we have
		\begin{align}
			\Lag_{\rho_{k}}\left(z^{k + 1} , \eta\right) - \Lag_{\rho_{k}}\left(\xi , \eta\right) & \leq \tau_{k}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\sigma}{2}\norm{\xi - z^{k + 1}}^{2} + \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) \nonumber \\
			& - \rho t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}. \label{L:FGLIter:0}
		\end{align}		
	\end{lemma}

\begin{proof}
		Since $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ is generated by FLAG, we obtain from \eqref{AlgoMapNiceProperty} after omitting the non-negative term $\left(\tau_{k}/2\right)\norm{z^{k + 1} - z^{k}}_{Q}^{2}$, that
		\begin{equation} \label{L:FGLIter:1}
			\Lag_{\rho_{k}}\left(z^{k + 1} , \lambda^{k}\right) - \Lag_{\rho_{k}}\left(\xi , \lambda^{k}\right) \leq \tau_{k}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\sigma}{2}\norm{\xi - z^{k + 1}}^{2} - \frac{\delta\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2}.
		\end{equation}
		From the multiplier update \eqref{FGL:MultiStep} and the three-points identity \eqref{Pyth}, we obtain, for all $\eta \in \real^{m}$,
		\begin{align}
			\act{\eta - y^{k} , \AAA z^{k + 1} - b}  = \frac{1}{\mu\rho_{k}}\act{\eta - y^{k} , y^{k + 1} - y^{k}} & = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{1}{2\mu\rho_{k}}\norm{y^{k + 1} - y^{k}}^{2} \nonumber \\
			& = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{\mu\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2}. \label{L:FGLIter:2}
		\end{align}
		Using the update rule of the sequence $\seq{t}{k}$ (\cf \eqref{FGL:Tk}) we have that $\rho_{k}\left(t_{k} - 1\right) =\rho t_{k - 1}^{p} $ and thus
		\begin{equation*}
			\lambda^{k} = y^{k} + \rho_{k}\left(t_{k} - 1\right)\left(\AAA x^{k} -b\right) = y^{k} + \rho t_{k - 1}^{p}\left(\AAA x^{k} -b\right).
		\end{equation*}
		Using this together with \eqref{L:FGLIter:2} yields, for all $\eta \in \real^{m}$, that
		\begin{align}		
			\act{\eta - \lambda^{k} , \AAA z^{k + 1} - b} & = \act{\eta - y^{k} , \AAA z^{k + 1} - b} - \rho t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b} \nonumber \\
			& = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{\mu\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2} - \rho t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}. \label{L:FGLIter:3}
		\end{align}
		Adding \eqref{L:FGLIter:1} to \eqref{L:FGLIter:3} yields (recall that $\mu \leq \delta$) the desired result.
	\end{proof}

Since $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ is generated by FLAG, we obtain from \eqref{AlgoMapNiceProperty} after omitting the non-negative term $\left(\tau_{k}/2\right)\norm{z^{k + 1} - z^{k}}_{Q}^{2}$, that
\begin{equation} \label{L:FGLIter:1}
	\Lag_{\rho_{k}}\left(z^{k + 1} , \lambda^{k}\right) - \Lag_{\rho_{k}}\left(\xi , \lambda^{k}\right) \leq \tau_{k}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\sigma}{2}\norm{\xi - z^{k + 1}}^{2} - \frac{\delta\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2}.
\end{equation}

From the multiplier update \eqref{FGL:MultiStep} and the three-points identity \eqref{Pyth}, we obtain, for all $\eta \in \real^{m}$,
\begin{align}
	\act{\eta - y^{k} , \AAA z^{k + 1} - b}  = \frac{1}{\mu\rho_{k}}\act{\eta - y^{k} , y^{k + 1} - y^{k}} & = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{1}{2\mu\rho_{k}}\norm{y^{k + 1} - y^{k}}^{2} \nonumber \\
	& = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{\mu\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2}. \label{L:FGLIter:2}
\end{align}

Using the update rule of the sequence $\seq{t}{k}$ (\cf \eqref{FGL:Tk}) we have that $\rho_{k}\left(t_{k} - 1\right) =\rho t_{k - 1}^{p} $ and thus
\begin{equation*}
	\lambda^{k} = y^{k} + \rho_{k}\left(t_{k} - 1\right)\left(\AAA x^{k} -b\right) = y^{k} + \rho t_{k - 1}^{p}\left(\AAA x^{k} -b\right).
\end{equation*}

Using this together with \eqref{L:FGLIter:2} yields, for all $\eta \in \real^{m}$, that
\begin{align}		
	\act{\eta - \lambda^{k} , \AAA z^{k + 1} - b} & = \act{\eta - y^{k} , \AAA z^{k + 1} - b} - \rho t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b} \nonumber \\
	& = \frac{1}{\mu\rho_{k}}\Delta\left(\eta , y^{k} , y^{k + 1}\right) + \frac{\mu\rho_{k}}{2}\norm{\AAA z^{k + 1} - b}^{2} - \rho t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}. \label{L:FGLIter:3}
\end{align}

\begin{lemma} \label{L:FGLMain}
		Let $\left\{ \left(x^{k} , z^{k} , y^{k}\right) \right\}_{k \in \nn}$ be a sequence generated by FLAG. Then, for any $\xi \in \FFF$, $\eta \in \real^{m}$ and $k \geq 0$, we have
		\begin{equation*}
			t_{k}^{p}s_{k + 1} - t_{k - 1}^{p}s_{k} \leq \frac{\tau_{k}\rho_{k}}{\rho}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\rho_{k}\sigma}{2\rho}\norm{\xi - z^{k + 1}}^{2} + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right),
		\end{equation*}
		where $s_{k} = \Lag_{\rho t_{k - 1}^{p}}\left(x^{k} , \eta\right) - \Lag_{\rho t_{k - 1}^{p}}\left(\xi , \eta\right)$ (\cf \ref{laggap}).
	\end{lemma}

\begin{proof}
		Since $x^{k + 1} = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}$ (\cf \eqref{FGL:AccStep}) we obtain from the convexity of $\Psi\left(\cdot\right)$ that
		\begin{equation*}
			\Psi\left(x^{k + 1}\right) \leq \left(1 - t_{k}^{-1}\right)\Psi\left(x^{k}\right) + t_{k}^{-1}\Psi\left(z^{k + 1}\right).
		\end{equation*}
		Therefore, multiplying both sides by $t_{k}^{p}$ (recalling that $t_{k}^{p} - t_{k}^{p - 1} = t_{k - 1}^{p}$), we obtain
		\begin{equation*}
			t_{k}^{p}\left(\Psi\left(x^{k + 1}\right) - \Psi\left(\xi\right)\right) - t_{k - 1}^{p}\left(\Psi\left(x^{k}\right) - \Psi\left(\xi\right)\right) \leq t_{k}^{p - 1}\left(\Psi\left(z^{k + 1}\right) - \Psi\left(\xi\right)\right).
		\end{equation*}
		In addition, using again \eqref{FGL:AccStep}, yields that
		\begin{equation*}
			t_{k}^{p}\act{\eta , \AAA x^{k + 1} - b} - t_{k - 1}^{p}\act{\eta , \AAA x^{k} - b} = t_{k}^{p - 1}\act{\eta , \AAA z^{k + 1} - b}.
		\end{equation*}			
		Combining these two facts yields (using the definition of the Lagrangian $\Lag$)
		\begin{equation} \label{L:FGLMain:1}
			t_{k}^{p}\left(\Lag\left(x^{k + 1} , \eta\right) - \Lag\left(\xi , \eta\right)\right) - t_{k - 1}^{p}\left(\Lag\left(x^{k} , \eta\right) - \Lag\left(\xi , \eta\right)\right) \leq t_{k}^{p - 1}\left(\Lag\left(z^{k + 1} , \eta\right) - \Lag\left(\xi , \eta\right)\right).
		\end{equation}			
		Now, we will again use the relation $x^{k + 1} = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}$ to obtain
		\begin{equation*}
			\norm{\AAA x^{k + 1} - b}^{2}  = \left(1 - t_{k}^{-1}\right)^{2}\norm{\AAA x^{k} - b}^{2} + t_{k}^{-2}\norm{\AAA z^{k + 1} - b}^{2} + 2\left(1 - t_{k}^{-1}\right)t_{k}^{-1}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}.
		\end{equation*}		
		Multiplying both sides of the above equality by $\rho t_{k}^{2p}/2$ (recalling $\rho_{k} = \rho t_{k}^{p - 1}$ and $t_{k}^{p} - t_{k}^{p - 1} = t_{k - 1}^{p}$) yields
		\begin{align}
			\frac{\rho t_{k}^{2p}}{2}\norm{\AAA x^{k + 1} - b}^{2} - \frac{\rho t_{k - 1}^{2p}}{2}\norm{\AAA x^{k} - b}^{2} = \frac{\rho_{k}t_{k}^{p - 1}}{2}\norm{\AAA z^{k + 1} - b}^{2} + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}. \label{L:FGLMain:2}
		\end{align}
		Therefore, adding \eqref{L:FGLMain:1} to \eqref{L:FGLMain:2} yields (recall that $\norm{\AAA\xi - b}^{2} = 0$) with $s_{k} = \Lag_{\rho t_{k - 1}^{p}}\left(x^{k} , \eta\right) - \Lag_{\rho t_{k - 1}^{p}}\left(\xi , \eta\right)$,
		\begin{equation*}
			t_{k}^{p}s_{k + 1} - t_{k - 1}^{p}s_{k} \leq t_{k}^{p - 1}\left(\Lag_{\rho_{k}}\left(z^{k + 1} , \eta\right) - \Lag_{\rho_{k}}\left(\xi , \eta\right)\right) + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}.
		\end{equation*}			
		From Lemma \ref{L:FGLIter}, after we multiplied both sides of \eqref{L:FGLIter:0} by $t_{k}^{p - 1}$ (recall that $\rho_{k} = \rho t_{k}^{p - 1}$), we obtain that
		\begin{align*}
			t_{k}^{p - 1}\left(\Lag_{\rho_{k}}\left(z^{k + 1} , \eta\right) - \Lag_{\rho_{k}}\left(\xi , \eta\right)\right) + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b} & \leq \frac{\tau_{k}\rho_{k}}{\rho}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\rho_{k}\sigma}{2\rho}\norm{\xi - z^{k + 1}}^{2} \\
			& + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right).
		\end{align*}		
		By combining the last two inequalities, we thus get
		\begin{equation*}
			t_{k}^{p}s_{k + 1} - t_{k - 1}^{p}s_{k} \leq \frac{\tau_{k}\rho_{k}}{\rho}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\rho_{k}\sigma}{2\rho}\norm{\xi - z^{k + 1}}^{2} + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right),
		\end{equation*}				
		which proves the desired result.
	\end{proof}

Since $x^{k + 1} = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}$ (\cf \eqref{FGL:AccStep}) we obtain from the convexity of $\Psi\left(\cdot\right)$ that
\begin{equation*}
	\Psi\left(x^{k + 1}\right) \leq \left(1 - t_{k}^{-1}\right)\Psi\left(x^{k}\right) + t_{k}^{-1}\Psi\left(z^{k + 1}\right).
\end{equation*}

Therefore, multiplying both sides by $t_{k}^{p}$ (recalling that $t_{k}^{p} - t_{k}^{p - 1} = t_{k - 1}^{p}$), we obtain
\begin{equation*}
	t_{k}^{p}\left(\Psi\left(x^{k + 1}\right) - \Psi\left(\xi\right)\right) - t_{k - 1}^{p}\left(\Psi\left(x^{k}\right) - \Psi\left(\xi\right)\right) \leq t_{k}^{p - 1}\left(\Psi\left(z^{k + 1}\right) - \Psi\left(\xi\right)\right).
\end{equation*}

In addition, using again \eqref{FGL:AccStep}, yields that
\begin{equation*}
	t_{k}^{p}\act{\eta , \AAA x^{k + 1} - b} - t_{k - 1}^{p}\act{\eta , \AAA x^{k} - b} = t_{k}^{p - 1}\act{\eta , \AAA z^{k + 1} - b}.
\end{equation*}

Combining these two facts yields (using the definition of the Lagrangian $\Lag$)
\begin{equation} \label{L:FGLMain:1}
	t_{k}^{p}\left(\Lag\left(x^{k + 1} , \eta\right) - \Lag\left(\xi , \eta\right)\right) - t_{k - 1}^{p}\left(\Lag\left(x^{k} , \eta\right) - \Lag\left(\xi , \eta\right)\right) \leq t_{k}^{p - 1}\left(\Lag\left(z^{k + 1} , \eta\right) - \Lag\left(\xi , \eta\right)\right).
\end{equation}

Now, we will again use the relation $x^{k + 1} = \left(1 - t_{k}^{-1}\right)x^{k} + t_{k}^{-1}z^{k + 1}$ to obtain
\begin{equation*}
	\norm{\AAA x^{k + 1} - b}^{2}  = \left(1 - t_{k}^{-1}\right)^{2}\norm{\AAA x^{k} - b}^{2} + t_{k}^{-2}\norm{\AAA z^{k + 1} - b}^{2} + 2\left(1 - t_{k}^{-1}\right)t_{k}^{-1}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}.
\end{equation*}

Multiplying both sides of the above equality by $\rho t_{k}^{2p}/2$ (recalling $\rho_{k} = \rho t_{k}^{p - 1}$ and $t_{k}^{p} - t_{k}^{p - 1} = t_{k - 1}^{p}$) yields
\begin{align}
	\frac{\rho t_{k}^{2p}}{2}\norm{\AAA x^{k + 1} - b}^{2} - \frac{\rho t_{k - 1}^{2p}}{2}\norm{\AAA x^{k} - b}^{2} = \frac{\rho_{k}t_{k}^{p - 1}}{2}\norm{\AAA z^{k + 1} - b}^{2} + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}. \label{L:FGLMain:2}
\end{align}

Therefore, adding \eqref{L:FGLMain:1} to \eqref{L:FGLMain:2} yields (recall that $\norm{\AAA\xi - b}^{2} = 0$) with $s_{k} = \Lag_{\rho t_{k - 1}^{p}}\left(x^{k} , \eta\right) - \Lag_{\rho t_{k - 1}^{p}}\left(\xi , \eta\right)$,
\begin{equation*}
	t_{k}^{p}s_{k + 1} - t_{k - 1}^{p}s_{k} \leq t_{k}^{p - 1}\left(\Lag_{\rho_{k}}\left(z^{k + 1} , \eta\right) - \Lag_{\rho_{k}}\left(\xi , \eta\right)\right) + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b}.
\end{equation*}

From Lemma \ref{L:FGLIter}, after we multiplied both sides of \eqref{L:FGLIter:0} by $t_{k}^{p - 1}$ (recall that $\rho_{k} = \rho t_{k}^{p - 1}$), we obtain that
\begin{align*}
	t_{k}^{p - 1}\left(\Lag_{\rho_{k}}\left(z^{k + 1} , \eta\right) - \Lag_{\rho_{k}}\left(\xi , \eta\right)\right) + \rho_{k}t_{k - 1}^{p}\act{\AAA x^{k} - b , \AAA z^{k + 1} - b} & \leq \frac{\tau_{k}\rho_{k}}{\rho}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\rho_{k}\sigma}{2\rho}\norm{\xi - z^{k + 1}}^{2} \\
	& + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right).
\end{align*}

By combining the last two inequalities, we thus get
\begin{equation*}
	t_{k}^{p}s_{k + 1} - t_{k - 1}^{p}s_{k} \leq \frac{\tau_{k}\rho_{k}}{\rho}\Delta_{P}\left(\xi , z^{k} , z^{k + 1}\right) - \frac{\rho_{k}\sigma}{2\rho}\norm{\xi - z^{k + 1}}^{2} + \frac{1}{\mu\rho}\Delta\left(\eta , y^{k} , y^{k + 1}\right),
\end{equation*}				
which proves the desired result.

\begin{lemma} \label{L:Tk}
		Let $\seq{t}{k}$ be the sequence of positive numbers generated from $t_{0} = 1$ via the equation $t_{k + 1}^{p} - t_{k}^{p} = t_{k + 1}^{p - 1}$, with $p = 1$ or $p = 2$. Then, for any $k \geq 0$, we have
	\begin{itemize}
		\item[$\rm{(i)}$] For $p = 1$, we have $t_{k} = k + 1$.
		\item[$\rm{(ii)}$] For $p = 2$, we have $t_{k} \geq \left(k + 1\right)/2$. Moreover, one has $t_{k + 1}^{2} \leq t_{k}^{2} + 2t_{k}$.
	\end{itemize}				
	\end{lemma}

\begin{proof}
		The first item is immediate as well as the first part of the second item (see, for instance, \cite[Lemma 4.3]{BT2009}). Moreover, note that by the given recursion $t_{k + 1}^{2} - t_{k}^{2} = t_{k + 1}$, one also has $t_{k + 1} = t_{k} + t_{k + 1}/\left(t_{k} + t_{k + 1}\right)$, and hence it follows that $t_{k + 1}^{2} = t_{k}^{2} + t_{k + 1} \leq t_{k}^{2} + 2t_{k}$, since $t_{k} \geq 1$.
	\end{proof}

From Lemma \ref{L:FGLMain}, after we substitute $\xi = x^{\ast}$ and $p = 2$ (recall that $\rho_{k} = \rho t_{k}$ and $\tau_{k} = t_{k}$), we obtain
